  function boom(x, y, r) { G.fx.push({ ring: 1, x: x, y: y, r: r, l: 0.35, L: 0.35 }); spark(x, y, ['#f97316', '#fbbf24', '#78716c', '#fff'], 14); }
  /* ----- hiệu ứng lửa & khói (bản 2026.11.07-7) ----- */
