    banner(RAIN[k].e + ' ' + RAIN[k].n.toUpperCase() + '!', RAIN[k].info); sfx(k === 'snow' ? 'ice' : k === 'meteor' ? 'launch' : k === 'fire' ? 'fire' : 'horn');
