    try { if (window.farmEarn && (vnd || G.ok)) window.farmEarn('castle', vnd, G.ok, tp.id); } catch (e) {}
    if (win) { try { localStorage.setItem('farm6_pass', String(Date.now())); } catch (e) {} }
