      if (!unlocked(tp)) { var list = DATA.topics.filter(function (t) { return t.g === tp.g; }); alertMap('🔒 Hãy bảo vệ kho từ "' + list[list.indexOf(tp) - 1].n + '" trước để mở kho này.'); return; }
